CREATE ROLE app_user NOSUPERUSER NOBYPASSRLS;
CREATE TABLE tenants(id uuid PRIMARY KEY,name text);
CREATE TABLE users(id uuid PRIMARY KEY,full_name text);
CREATE TABLE memberships(tenant_id uuid,user_id uuid);
CREATE TABLE channels(id uuid PRIMARY KEY,tenant_id uuid,name text,type text DEFAULT 'web',status text DEFAULT 'active',credentials_enc text,settings jsonb DEFAULT '{}');
CREATE TABLE contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid,name text,email text,phone text,lifecycle text DEFAULT 'lead',tags text[] DEFAULT '{}',attributes jsonb DEFAULT '{}',owner_id uuid,archived_at timestamptz,merged_into_id uuid,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE contact_channels(tenant_id uuid,contact_id uuid,channel_id uuid,external_id text);
CREATE TABLE contact_consents(tenant_id uuid,contact_id uuid,channel_id uuid,status text,evidence text,updated_at timestamptz DEFAULT now(),UNIQUE(tenant_id,contact_id,channel_id));
CREATE TABLE contact_lists(id uuid PRIMARY KEY,tenant_id uuid,name text);
CREATE TABLE contact_list_members(tenant_id uuid,list_id uuid,contact_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE sequences(id uuid PRIMARY KEY,tenant_id uuid,name text,channel_id uuid,status text);
CREATE TABLE sequence_enrollments(tenant_id uuid,sequence_id uuid,contact_id uuid,status text,step_index int DEFAULT 0,next_run_at timestamptz,stop_reason text,updated_at timestamptz DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid,channel_id uuid,contact_id uuid,status text DEFAULT 'open',handled_by text DEFAULT 'bot',assigned_to uuid,department_id uuid,unread_count int DEFAULT 0,created_at timestamptz DEFAULT now(),last_message_at timestamptz DEFAULT now(),last_inbound_at timestamptz DEFAULT now());
CREATE TABLE departments(id uuid,tenant_id uuid,sla_minutes int,archived_at timestamptz);
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid,conversation_id uuid,channel_id uuid,direction text,sender_type text,type text,content jsonb DEFAULT '{}',status text,error text,is_internal boolean DEFAULT false,seq bigint GENERATED ALWAYS AS IDENTITY,external_id text,created_at timestamptz DEFAULT now());
CREATE TABLE flows(id uuid PRIMARY KEY,tenant_id uuid,name text,status text DEFAULT 'draft',published_version_id uuid,is_component boolean DEFAULT false,priority int DEFAULT 0,created_at timestamptz DEFAULT now());
CREATE TABLE flow_versions(id uuid PRIMARY KEY,tenant_id uuid,graph jsonb,triggers jsonb DEFAULT '[]',channel_ids uuid[] DEFAULT '{}');
CREATE TABLE flow_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid,conversation_id uuid,flow_id uuid,status text,wait_kind text,version_id uuid,expires_at timestamptz,created_at timestamptz DEFAULT now(),state jsonb DEFAULT '{}',updated_at timestamptz DEFAULT now());
CREATE TABLE crm_fields(tenant_id uuid,key text,type text);
CREATE TABLE crm_tasks(id uuid,tenant_id uuid,contact_id uuid,title text,due_at timestamptz,status text);
CREATE TABLE crm_pipelines(id uuid PRIMARY KEY,tenant_id uuid,name text,stages jsonb DEFAULT '["New","Qualified"]');
CREATE TABLE crm_deals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid,contact_id uuid,pipeline_id uuid,title text,stage text,value_cents bigint DEFAULT 0,currency text DEFAULT 'USD',status text DEFAULT 'open',owner_id uuid,updated_at timestamptz DEFAULT now());
CREATE TABLE crm_notes(id uuid,tenant_id uuid,contact_id uuid,created_by uuid,body text,created_at timestamptz DEFAULT now());
CREATE TABLE domain_events(id uuid,tenant_id uuid,type text,payload jsonb,status text,created_at timestamptz DEFAULT now(),seq bigint);
CREATE TABLE campaigns(id uuid PRIMARY KEY,tenant_id uuid,channel_id uuid,name text,status text,created_at timestamptz DEFAULT now(),scheduled_at timestamptz);
CREATE TABLE campaign_recipients(id uuid DEFAULT gen_random_uuid(),tenant_id uuid,campaign_id uuid,contact_id uuid,message_id uuid,status text);
CREATE TABLE outbound_jobs(id uuid PRIMARY KEY,tenant_id uuid,message_id uuid,status text,available_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),error text,attempts int DEFAULT 0,lease_until timestamptz);
CREATE FUNCTION normalize_contact_phone(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT regexp_replace(value,'[^0-9]','','g')$$;
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
CREATE POLICY isolate ON tenants USING(id=current_setting('app.tenant_id',true)::uuid);
DO $$DECLARE tab text;BEGIN
 FOR tab IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='tenant_id' LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);
  EXECUTE format('CREATE POLICY isolate ON %I USING(tenant_id=current_setting(''app.tenant_id'',true)::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'',true)::uuid)',tab);
 END LOOP;
END$$;
GRANT USAGE ON SCHEMA public TO app_user;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO app_user;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user;
